/**
 * Per-process bearer token for the dev-browser sidecar and its consumers.
 *
 * Phase 3 M1 (§5.3): the dev-browser HTTP server / relay (:9224) requires a
 * bearer token on every HTTP request and every WebSocket connection. The
 * token is generated by the spawning side (daemon / task bootstrap) and
 * distributed via env — never via RPC and never via the gateway:
 *
 *   - the sidecar receives `ACCOMPLISH_DEV_BROWSER_TOKEN` in its spawn env
 *     (browser/server.ts — ensureDevBrowserServer),
 *   - the dev-browser-mcp tool child receives the same value from the
 *     generated OpenCode config (generator-mcp.ts → browserEnv) and sends it
 *     as an Authorization header on every HTTP call.
 *
 * Precedence: an explicitly exported `ACCOMPLISH_DEV_BROWSER_TOKEN` env wins
 * (a launcher can seed the token); otherwise the first accessor call in the
 * process generates and memoizes a random 256-bit token, so every
 * consumer in the same process shares one value per daemon lifetime. If the
 * detached sidecar outlives a daemon restart it sees the new token as a
 * foreign request, gets killed by the self-heal path and relaunched with the
 * fresh token.
 */

import { generateServiceToken } from '../utils/service-token.js';

export const ACCOMPLISH_DEV_BROWSER_TOKEN_ENV = 'ACCOMPLISH_DEV_BROWSER_TOKEN';

let memoizedToken: string | null = null;

/** Read or lazily generate the dev-browser token for this process. */
export function getDevBrowserToken(): string {
  const fromEnv = process.env[ACCOMPLISH_DEV_BROWSER_TOKEN_ENV];
  if (fromEnv && fromEnv.trim().length > 0) {
    return fromEnv.trim();
  }
  if (!memoizedToken) {
    memoizedToken = generateServiceToken();
  }
  return memoizedToken;
}
